"use client";

import { animateSingleValue, motionValue, type Transition } from "motion/react";
import { subscribeMotionEnvironment } from "./motion-environment";
import type { MotionHostRef } from "./motion-ref";
import {
  collectMotionVisuals,
  createMotionTransaction,
  type MotionLease,
  type MotionRevision,
} from "./motion-transaction";

type Axis = "width" | "height";
export type GeometryTarget = {
  size: number;
  min?: number;
  max?: number;
  /** The adapter proves intermediate geometry preserves required content. */
  readable?: boolean;
  /** Known acyclic natural layout; percentage/ratio feedback uses native layout. */
  independent?: boolean;
  /** Only an adapter already owning a maintained native dimension supplies this. */
  resting?: string;
};
export type GeometryDestination = Partial<Record<Axis, GeometryTarget>>;
export type GeometryPolicy = { reduced: boolean; transition: Transition; available?: boolean };
type Reason = "commit" | "passive" | "focus";
type PixelCheck = { doc: Document; axis: Axis; size: number; used: number; accept(valid: boolean): void };

/** Batch CSS-pixel round trips in empty display probes, never caller content. */
function verifyPixels(checks: PixelCheck[]) {
  for (const doc of new Set(checks.map((check) => check.doc))) {
    const batch = checks.filter((check) => check.doc === doc),
      view = doc.defaultView;
    if (!doc.body || !view) {
      for (const check of batch) check.accept(false);
      continue;
    }
    const host = doc.createElement("div");
    host.setAttribute("data-cadence-geometry-probe", "");
    host.setAttribute("aria-hidden", "true");
    host.inert = true;
    host.style.cssText =
      "all:initial;position:fixed;top:0;left:0;width:0;height:0;overflow:clip;contain:strict;visibility:hidden;pointer-events:none";
    const root = host.attachShadow({ mode: "closed" });
    const probes = new Map<string, HTMLElement>();
    for (const check of batch) {
      const key = `${check.axis}/${check.size}`;
      if (probes.has(key)) continue;
      const probe = doc.createElement("div");
      probe.style.cssText = "all:initial;display:block;width:0;height:0;visibility:hidden";
      probe.style[check.axis] = `${check.size}px`;
      root.append(probe);
      probes.set(key, probe);
    }
    try {
      doc.body.append(host);
      const results = new Map([...probes].map(([key, probe]) => [key, view.getComputedStyle(probe)]));
      for (const check of batch)
        check.accept(Number.parseFloat(results.get(`${check.axis}/${check.size}`)?.[check.axis] ?? "") === check.used);
    } finally {
      host.remove();
    }
  }
}
type Adapter = {
  host: MotionHostRef<HTMLElement>;
  content: HTMLElement;
  axes: readonly Axis[];
  /** Native sizing adapter work is distinct from decorative participation. */
  maintained?: boolean;
  /** Read natural layout only. The one real content tree must be independent of the written axis. */
  measure(reason: Reason): GeometryDestination | null;
};

/** Layout dimensions, never transformed viewport rectangles. Unknown layout is not zero. */
function measurable(element: HTMLElement) {
  if (
    !element.isConnected ||
    (element.checkVisibility && !element.checkVisibility({ contentVisibilityAuto: true, visibilityProperty: true })) ||
    !element.getClientRects().length
  )
    return false;
  return true;
}

export function naturalGeometry(element: HTMLElement): { width: number; height: number } | null {
  if (!measurable(element)) return null;
  const css = element.ownerDocument.defaultView?.getComputedStyle(element);
  if (!css) return null;
  const width = Number.parseFloat(css.width);
  const height = Number.parseFloat(css.height);
  return Number.isFinite(width) && Number.isFinite(height) ? { width, height } : null;
}

/**
 * An explicitly registered, bounded compound scope. Commit only after a semantic
 * revision is accepted. Observers/environment/input never manufacture revisions.
 * One outer host owns each same-cause axis: descendants lay out at their native
 * destinations before the outer host is measured, not at child spring frames.
 */
export function createMeasuredGeometry(transaction = createMotionTransaction()) {
  const owners = new Set<ReturnType<typeof makeOwner>>();
  let policy: GeometryPolicy = { reduced: true, transition: { duration: 0 } };
  let closed = false;
  let flushing = false;
  let committed: { revision: MotionRevision; policy: string; instant: boolean } | null = null;
  const makeOwner = (adapter: Adapter) => {
    const { host, content } = adapter;
    const node = host.current;
    if (!node) throw new Error("Geometry registration requires its committed host");
    const identity = host.identity;
    const registration = transaction.register(node);
    const values = { width: motionValue(0), height: motionValue(0) };
    const effects: Partial<Record<Axis, Animation>> = {};
    const stops = new Set<() => void>();
    let baseline: GeometryDestination | null = null;
    let lease: MotionLease | null = null;
    let alive = true;
    let running = false;
    let restricted = false;
    let stamp = "";
    let writingMode = "";
    let sampled: Partial<Record<Axis, { size: number; velocity: number }>> = {};
    const current = () => alive && host.current === node && host.identity === identity && node.isConnected;
    const release = () => {
      for (const stop of stops) stop();
      stops.clear();
      for (const axis of ["width", "height"] as const) {
        values[axis].stop();
        effects[axis]?.cancel();
        delete effects[axis];
      }
    };
    const cancel = () => {
      lease?.cancel();
      release();
      running = false;
    };
    const owner = {
      adapter,
      node,
      current,
      baseline: () => baseline,
      restricted: () => restricted,
      capture() {
        sampled = {};
        if (!running || !current()) return;
        const box = naturalGeometry(node);
        if (!box) return;
        for (const axis of adapter.axes) {
          const size = box[axis],
            bounds = baseline?.[axis];
          let velocity = values[axis].getVelocity();
          if (
            (size <= (bounds?.min ?? 0) && velocity < 0) ||
            (size >= (bounds?.max ?? Number.POSITIVE_INFINITY) && velocity > 0)
          )
            velocity = 0;
          sampled[axis] = { size, velocity };
        }
      },
      read(reason: Reason) {
        if (!current() || !measurable(content)) {
          stamp = "";
          return null;
        }
        const result = adapter.measure(reason);
        // RO sizes are border-box layout units; rounding matches offset sizes.
        writingMode = content.ownerDocument.defaultView?.getComputedStyle(content).writingMode ?? "";
        const vertical = /^(vertical|sideways)/.test(writingMode);
        stamp = vertical
          ? `${content.offsetHeight}/${content.offsetWidth}`
          : `${content.offsetWidth}/${content.offsetHeight}`;
        return result;
      },
      release,
      cancel,
      verify(destination: GeometryDestination | null, checks: PixelCheck[]) {
        if (!destination) return null;
        const css = node.ownerDocument.defaultView?.getComputedStyle(node);
        const result = { ...destination };
        for (const axis of adapter.axes) {
          const target = result[axis];
          if (!target) continue;
          const used = Number.parseFloat(css?.[axis] ?? "");
          const min = Math.max(0, target.min ?? 0),
            max = target.max ?? Number.POSITIVE_INFINITY;
          const size = Math.min(max, Math.max(min, target.resting === "auto" ? used : target.size));
          if (!Number.isFinite(used) || !Number.isFinite(size) || max < min) {
            delete result[axis];
            continue;
          }
          const accept = (valid: boolean) => {
            if (!valid) delete result[axis];
            else result[axis] = { ...target, size, ...(target.max === target.size && size < max ? { max: size } : {}) };
          };
          if (used === size) accept(true);
          else checks.push({ doc: node.ownerDocument, axis, size, used, accept });
        }
        return result;
      },
      apply(destination: GeometryDestination | null, revision: MotionRevision | null, animated: Set<Axis>) {
        const previous = baseline;
        baseline = destination ? { ...destination } : null;
        if (!current() || !destination) {
          stamp = "";
          cancel();
          return;
        }
        const axes = (["width", "height"] as const).filter((axis) => destination[axis]);
        const active = running;
        running = false;
        if (revision)
          lease = registration.begin(revision, axes, { collectionVisuals: new Set([node]) }, () => {
            release();
            running = false;
          });
        else {
          cancel();
          lease = null;
        }
        let pending = 0;
        for (const axis of axes) {
          const target = destination[axis];
          if (!target) continue;
          const min = Math.max(0, target.min ?? 0);
          const max = target.max ?? Number.POSITIVE_INFINITY;
          const valid = Number.isFinite(target.size) && Number.isFinite(min) && max >= min;
          if (!valid) continue;
          const size = Math.min(max, Math.max(min, target.size));
          if (baseline) baseline[axis] = { ...target, size };
          // This maintained dimension belongs to the adapter, never caller CSS.
          if (target.resting !== undefined) node.style[axis] = target.resting;
          const start = active ? sampled[axis]?.size : previous?.[axis]?.size;
          if (
            !lease?.current() ||
            !animated.has(axis) ||
            !target.readable ||
            !target.independent ||
            !Number.isFinite(start) ||
            start === size ||
            typeof node.animate !== "function"
          ) {
            values[axis].jump(size);
            continue;
          }
          values[axis].jump(start as number);
          // A replace-effect overlays CSS without capturing/restoring caller
          // declarations. Cancelling exposes the latest auto/flex/grid policy.
          const effect = node.animate(
            { [axis]: `${Math.min(max, Math.max(min, start as number))}px` },
            { duration: 0, fill: "both" },
          );
          effects[axis] = effect;
          const permit = lease;
          const write = (value: number) => {
            if (current() && permit.current())
              (effect.effect as KeyframeEffect | null)?.setKeyframes({
                [axis]: `${Math.min(max, Math.max(min, value))}px`,
              });
          };
          const unsubscribe = values[axis].on("change", write);
          pending++;
          running = true;
          animateSingleValue(values[axis], size, {
            ...policy.transition,
            velocity: active ? sampled[axis]?.velocity : 0,
            onComplete: () => {
              unsubscribe();
              stops.delete(unsubscribe);
              if (!current() || !permit.current()) return;
              effect.cancel();
              if (effects[axis] === effect) delete effects[axis];
              if (!--pending) {
                running = false;
                permit.finish();
              }
            },
          });
          stops.add(unsubscribe);
        }
        if (!pending) lease?.finish();
      },
      dispose() {
        if (!alive) return;
        alive = false;
        owners.delete(owner);
        registration.dispose();
        release();
        for (const stop of stops) stop();
        observer.disconnect();
        attributes.disconnect();
        unsubscribeEnvironment();
        for (const event of ["focusin", "beforematch", "pointerdown", "beforeinput"])
          node.removeEventListener(event, input, true);
        view?.removeEventListener("resize", passive);
        view?.visualViewport?.removeEventListener("resize", passive);
        content.ownerDocument.fonts?.removeEventListener("loadingdone", passive);
        if (host.invalidate === owner.dispose) host.invalidate = undefined;
      },
    };
    const passive = () => flush(null, "passive");
    const delegated = () =>
      !adapter.maintained &&
      adapter.axes.every((axis) =>
        [...owners].some(
          (parent) => parent !== owner && parent.adapter.axes.includes(axis) && parent.node.contains(node),
        ),
      );
    const input = () => flush(null, "focus");
    const view = node.ownerDocument.defaultView;
    const observer = new ResizeObserver((entries) => {
      if (delegated()) return;
      const entry = entries.find((entry) => entry.target === content);
      const box = entry?.borderBoxSize?.[0];
      if (box && `${Math.round(box.inlineSize)}/${Math.round(box.blockSize)}` === stamp) return;
      passive();
    });
    observer.observe(content, { box: "border-box" });
    const attributes = new MutationObserver(() => {
      if (!delegated() && view?.getComputedStyle(content).writingMode !== writingMode) passive();
    });
    attributes.observe(content, { attributes: true, attributeFilter: ["style", "class"] });
    const unsubscribeEnvironment = subscribeMotionEnvironment(node.ownerDocument, (state) => {
      restricted = state.hidden || state.immediate || state.reduced;
      if (restricted) passive();
    });
    for (const event of ["focusin", "beforematch", "pointerdown", "beforeinput"])
      node.addEventListener(event, input, true);
    view?.addEventListener("resize", passive);
    view?.visualViewport?.addEventListener("resize", passive);
    content.ownerDocument.fonts?.addEventListener("loadingdone", passive);
    host.invalidate = owner.dispose;
    return owner;
  };
  const flush = (revision: MotionRevision | null, reason: Reason) => {
    if (closed || flushing) return;
    flushing = true;
    try {
      const registered = [...owners];
      for (const owner of registered) if (!owner.current()) owner.apply(null, null, new Set());
      const group = registered.filter((owner) => owner.current());
      // Preflight before visible-box capture, then release and resolve native
      // destinations in batches. Scalar callbacks never measure layout.
      const delegated = (owner: (typeof group)[number], axis: Axis) =>
        group.some(
          (parent) => parent !== owner && parent.adapter.axes.includes(axis) && parent.node.contains(owner.node),
        );
      const participants = group.filter((owner) => owner.adapter.axes.some((axis) => !delegated(owner, axis)));
      if (!collectMotionVisuals(new Set(participants.map((owner) => owner.node)))) {
        for (const owner of group) owner.apply(null, null, new Set());
        return;
      }
      for (const owner of participants) owner.capture();
      for (const owner of group) owner.release();
      const destinations = new Map<(typeof group)[number], GeometryDestination | null>();
      const maintained = group.filter((owner) => owner.adapter.maintained);
      const depth = (owner: (typeof group)[number]) =>
        group.filter((parent) => parent !== owner && parent.node.contains(owner.node)).length;
      // Native maintained dimensions resolve leaf-first in depth batches. This
      // is semantic layout work, never a collection of decorative child springs.
      for (const level of [...new Set(maintained.map(depth))].sort((a, b) => b - a)) {
        const batch = maintained.filter((owner) => depth(owner) === level);
        for (const owner of batch) destinations.set(owner, owner.read(reason));
        for (const owner of batch)
          for (const axis of owner.adapter.axes) {
            const resting = destinations.get(owner)?.[axis]?.resting;
            if (resting !== undefined) owner.node.style[axis] = resting;
          }
      }
      for (const owner of participants) if (!destinations.has(owner)) destinations.set(owner, owner.read(reason));
      const checks: PixelCheck[] = [];
      for (const [owner, destination] of destinations) destinations.set(owner, owner.verify(destination, checks));
      verifyPixels(checks);
      const immediate =
        policy.reduced || policy.available === false || policy.transition.duration === 0 || !revision?.current();
      for (const owner of group) {
        const focused = owner.node.contains(owner.node.ownerDocument.activeElement);
        const axes = new Set<Axis>();
        if (!immediate && !focused && !owner.restricted())
          for (const axis of owner.adapter.axes) if (!delegated(owner, axis)) axes.add(axis);
        owner.apply(destinations.get(owner) ?? null, revision, axes);
      }
    } catch (error) {
      for (const owner of owners) owner.apply(null, null, new Set());
      throw error;
    } finally {
      flushing = false;
    }
  };
  return {
    register(adapter: Adapter) {
      if (closed) throw new Error("Geometry scope is closed");
      const owner = makeOwner(adapter);
      owners.add(owner);
      committed = null;
      return owner.dispose;
    },
    commit(revision: MotionRevision, next: GeometryPolicy) {
      policy = next;
      const signature = JSON.stringify(next);
      if (committed?.revision === revision && committed.policy === signature) return;
      const instant = next.reduced || next.available === false || next.transition.duration === 0;
      const restoring = committed?.revision === revision && committed.instant && !instant;
      committed = { revision, policy: signature, instant };
      flush(restoring ? null : revision, "commit");
    },
    settle() {
      flush(null, "passive");
    },
    dispose() {
      closed = true;
      for (const owner of [...owners]) owner.dispose();
    },
  };
}

"use client";

import { animateSingleValue, motionValue, type Transition } from "motion/react";
import { subscribeMotionEnvironment } from "./motion-environment";
import type { MotionHostRef } from "./motion-ref";
import { createMotionTransaction, type MotionLease, type MotionRevision } from "./motion-transaction";

/** Native offcanvas endpoints, in the common shell's physical CSS-pixel space. */
export type SizeLinkedDestination = { gap: number; width: number; sign: -1 | 1 };

/**
 * One physical size scalar, two disjoint property owners. The panel projects
 * the gap's *rendered clamped size*, never a second spring or a layout read.
 * Native CSS already owns both destinations; cancelling overlays exposes it.
 */
export function createSizeLinkedGeometry(
  gapHost: MotionHostRef<HTMLElement>,
  panelHost: MotionHostRef<HTMLElement>,
  transaction = createMotionTransaction(),
) {
  const gap = gapHost.current,
    panel = panelHost.current;
  if (!gap || !panel) throw new Error("Size-linked geometry requires both committed hosts");
  const gapIdentity = gapHost.identity,
    panelIdentity = panelHost.identity;
  const size = motionValue(0);
  const gapOwner = transaction.register(gap),
    panelOwner = transaction.register(panel);
  let baseline: SizeLinkedDestination | null = null;
  let previous: MotionRevision | null = null;
  let signature = "";
  let running = false;
  let alive = true;
  let restricted = false;
  let bounds = [0, 0];
  let gapEffect: Animation | null = null,
    panelEffect: Animation | null = null;
  let gapLease: MotionLease | null = null,
    panelLease: MotionLease | null = null;
  const current = () =>
    alive &&
    gapHost.current === gap &&
    panelHost.current === panel &&
    gapHost.identity === gapIdentity &&
    panelHost.identity === panelIdentity &&
    gap.isConnected &&
    panel.isConnected;
  const rendered = () => Math.max(bounds[0] ?? 0, Math.min(bounds[1] ?? 0, size.get()));
  const release = () => {
    running = false;
    size.stop();
    gapEffect?.cancel();
    panelEffect?.cancel();
    gapEffect = panelEffect = null;
    const oldGap = gapLease,
      oldPanel = panelLease;
    gapLease = panelLease = null;
    oldGap?.cancel();
    oldPanel?.cancel();
  };
  const write = () => {
    if (!current() || !gapLease?.current() || !panelLease?.current() || !baseline) return;
    const visible = rendered();
    (gapEffect?.effect as KeyframeEffect | null)?.setKeyframes({ width: `${visible}px` });
    (panelEffect?.effect as KeyframeEffect | null)?.setKeyframes({
      transform: `translateX(${-baseline.sign * (visible - baseline.gap)}px)`,
    });
  };
  const off = size.on("change", write);
  const unsubscribe = subscribeMotionEnvironment(panel.ownerDocument, (environment) => {
    restricted = environment.hidden || environment.reduced || environment.immediate;
    if (restricted) {
      release();
      baseline = null;
    }
  });
  return {
    /** Must run before measuring native destinations, including active/outgoing work. */
    prepare(revision: MotionRevision, transition: Transition, immediate: boolean) {
      if (previous === revision && signature === JSON.stringify(transition) && !immediate && !restricted) return null;
      const sample = running
        ? { size: rendered(), velocity: size.get() === rendered() ? size.getVelocity() : 0 }
        : null;
      const permitted = transaction.preflightVisuals(new Set([gap, panel]));
      release();
      return { sample, permitted };
    },
    commit(
      revision: MotionRevision,
      destination: SizeLinkedDestination | null,
      transition: Transition,
      immediate: boolean,
      prepared: { sample: { size: number; velocity: number } | null; permitted: boolean },
    ) {
      if (
        destination &&
        (!Number.isFinite(destination.gap) ||
          !Number.isFinite(destination.width) ||
          destination.width <= 0 ||
          destination.gap < 0 ||
          destination.gap > destination.width)
      )
        destination = null;
      const origin = baseline;
      baseline = destination;
      const clock = JSON.stringify(transition);
      const same = previous === revision;
      const retime = signature !== clock;
      previous = revision;
      signature = clock;
      if (!current() || !destination) return;
      const { gap: target, width, sign } = destination;
      if (
        !origin ||
        (same && (!retime || !prepared.sample)) ||
        origin.width !== width ||
        origin.sign !== sign ||
        !prepared.permitted ||
        immediate ||
        restricted ||
        transition.duration === 0 ||
        !revision.current() ||
        !gap.animate ||
        !panel.animate ||
        ![target, width].every(Number.isFinite) ||
        width <= 0 ||
        target < 0 ||
        target > width
      ) {
        size.jump(target);
        return;
      }
      const start = prepared.sample?.size ?? origin.gap;
      if (start === target) return;
      bounds = [Math.min(start, target), Math.max(start, target)];
      size.jump(start);
      gapLease = gapOwner.begin(revision, ["width"], { collectionVisuals: new Set([gap, panel]) }, release);
      panelLease = panelOwner.begin(revision, ["transform"], {}, release);
      if (!gapLease || !panelLease) {
        release();
        return;
      }
      const permit = gapLease,
        projectionPermit = panelLease;
      gapEffect = gap.animate({}, { duration: 0, fill: "both" });
      panelEffect = panel.animate({}, { duration: 0, fill: "both" });
      running = true;
      write();
      animateSingleValue(size, target, {
        ...transition,
        velocity: prepared.sample?.velocity ?? 0,
        onComplete() {
          if (!current() || !permit.current() || !projectionPermit.current()) return;
          release();
        },
      });
    },
    invalidate() {
      release();
      baseline = null;
    },
    dispose() {
      alive = false;
      gapOwner.dispose();
      panelOwner.dispose();
      release();
      off();
      unsubscribe();
    },
  };
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import { naturalGeometry } from "./measured-geometry";
import { bindMotionParameters, geometryCompact, layoutSidebar } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { usePresentationScope } from "./motion-presence";
import type { MotionHostRef } from "./motion-ref";
import { createMotionTransaction } from "./motion-transaction";
import { useCadenceMotion } from "./provider";
import { createSizeLinkedGeometry, type SizeLinkedDestination } from "./size-linked-geometry";

/** Desktop offcanvas adapter. Icon label-lane choreography remains a separate adoption. */
export function useSidebarGeometry(
  gapHost: MotionHostRef<HTMLDivElement>,
  panelHost: MotionHostRef<HTMLDivElement>,
  state: string,
  configuration: string,
  enabled: boolean,
) {
  const parent = usePresentationScope();
  const [transaction] = useState(() => parent?.transaction ?? createMotionTransaction());
  const cm = useCadenceMotion(panelHost);
  const latest = useRef({ cm, state, enabled });
  const connection = useRef<{ dispose(): void; flush(): void } | null>(null);
  // biome-ignore lint/correctness/useExhaustiveDependencies: a side/variant/breakpoint change retires the physical projection before establishing a new baseline
  useLayoutEffect(() => {
    const gap = gapHost.current,
      panel = panelHost.current;
    if (!gap || !panel || !enabled) return;
    const wrapper = gap.closest<HTMLElement>('[data-slot="sidebar-wrapper"]');
    if (!wrapper || panel.parentElement !== gap.parentElement) return;
    const projection = createSizeLinkedGeometry(gapHost, panelHost, transaction);
    let alive = true;
    const captures = new Set<EventTarget>();
    const doc = panel.ownerDocument,
      view = doc.defaultView;
    const ancestors: HTMLElement[] = [];
    for (
      let element: HTMLElement | null = panel.parentElement;
      element && ancestors.length < 32;
      element = element.parentElement
    )
      ancestors.push(element);
    const editor = () => {
      const focused = doc.activeElement;
      return Boolean(
        captures.size ||
          (focused instanceof HTMLElement &&
            wrapper.contains(focused) &&
            (focused.matches("input,textarea,select") || focused.isContentEditable)),
      );
    };
    const measure = (): SizeLinkedDestination | null => {
      const box = naturalGeometry(gap),
        shell = naturalGeometry(panel);
      if (!box || !shell || !view) return null;
      // An unexamined outer transform is not a proven coordinate space.
      if (ancestors.at(-1)?.parentElement) return null;
      const paint = view.getComputedStyle(panel),
        gapPaint = view.getComputedStyle(gap);
      const sign = panel.dataset.side === "right" ? 1 : -1;
      const closed = latest.current.state === "collapsed";
      if (
        paint.boxSizing !== "border-box" ||
        gapPaint.boxSizing !== "border-box" ||
        paint.transform !== "none" ||
        paint.translate !== "none" ||
        paint.rotate !== "none" ||
        paint.scale !== "none" ||
        !["fixed", "absolute"].includes(paint.position) ||
        Number.parseFloat(paint[sign === 1 ? "right" : "left"]) !== (closed ? -shell.width : 0) ||
        (closed ? box.width !== 0 : box.width !== shell.width)
      )
        return null;
      for (const element of ancestors) {
        const css = view.getComputedStyle(element);
        const matrix = css.transform === "none" ? null : new DOMMatrixReadOnly(css.transform);
        if (
          css.rotate !== "none" ||
          css.scale !== "none" ||
          css.perspective !== "none" ||
          css.offsetPath !== "none" ||
          (matrix &&
            !matrix.isIdentity &&
            (!matrix.is2D || matrix.a !== 1 || matrix.d !== 1 || matrix.b !== 0 || matrix.c !== 0))
        )
          return null;
      }
      return { gap: box.width, width: shell.width, sign };
    };
    const flush = (settle = false) => {
      if (!alive || gapHost.current !== gap || panelHost.current !== panel) return;
      const { cm: policy, state: target, enabled: available } = latest.current;
      const size = policy.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
      const layout = policy.parameters(bindMotionParameters(layoutSidebar, "layout.move/size-linked"));
      const transition = size.kind === "geometry" ? size.transition : { duration: 0 };
      const immediate =
        settle ||
        policy.reduced ||
        !available ||
        layout.kind !== "layout" ||
        Boolean(parent && !parent.available()) ||
        editor();
      const revision = transaction.revision("layout", target, gap);
      const prepared = projection.prepare(revision, transition, immediate);
      if (prepared) projection.commit(revision, prepared.permitted ? measure() : null, transition, immediate, prepared);
    };
    const passive = () => {
      if (alive) {
        projection.invalidate();
        flush(true);
      }
    };
    const input = (event: Event) => {
      if (event.type === "gotpointercapture" && event.target) captures.add(event.target);
      if (event.type === "lostpointercapture" && event.target) captures.delete(event.target);
      if (editor()) passive();
    };
    const observer = new MutationObserver(passive);
    for (const element of [panel, ...ancestors])
      observer.observe(element, { attributes: true, attributeFilter: ["class", "style", "dir", "hidden"] });
    let stamp = `${wrapper.offsetWidth}/${wrapper.offsetHeight}`;
    const resize = new ResizeObserver(() => {
      const next = `${wrapper.offsetWidth}/${wrapper.offsetHeight}`;
      if (next !== stamp) passive();
      stamp = next;
    });
    resize.observe(wrapper);
    const environment = subscribeMotionEnvironment(doc, passive);
    for (const event of ["focusin", "beforeinput", "gotpointercapture", "lostpointercapture"])
      wrapper.addEventListener(event, input, true);
    view?.addEventListener("resize", passive);
    view?.visualViewport?.addEventListener("resize", passive);
    view?.visualViewport?.addEventListener("scroll", passive);
    const dispose = () => {
      if (!alive) return;
      alive = false;
      projection.dispose();
      observer.disconnect();
      resize.disconnect();
      environment();
      for (const event of ["focusin", "beforeinput", "gotpointercapture", "lostpointercapture"])
        wrapper.removeEventListener(event, input, true);
      view?.removeEventListener("resize", passive);
      view?.visualViewport?.removeEventListener("resize", passive);
      view?.visualViewport?.removeEventListener("scroll", passive);
      if (gapHost.invalidate === dispose) gapHost.invalidate = undefined;
      if (panelHost.invalidate === dispose) panelHost.invalidate = undefined;
    };
    gapHost.invalidate = panelHost.invalidate = dispose;
    connection.current = { dispose, flush };
    return () => {
      dispose();
      connection.current = null;
    };
  }, [configuration, enabled, gapHost, panelHost, transaction, parent]);
  useLayoutEffect(() => {
    latest.current = { cm, state, enabled };
    connection.current?.flush();
  });
}
